   element carries the theme — works with data-theme on <html> OR <body>. (An alias
   declared only on :root substitutes the LIGHT token at :root and that computed value
   inherits down, defeating a dark theme set lower in the tree.)
   ===================================================================== */
:root, [data-theme="light"], [data-theme="dark"]{
  /* surfaces / text */
  --page:            var(--background-default);          /* #FFF / #000  app canvas      */
  --surface:         var(--tertiary-background-default); /* #FFF / #1D1D1D  raised card  */
  --surface-hover:   var(--tertiary-background-hover);   /* #F3F3F3 / #212121            */
  --surface-pressed: var(--tertiary-background-pressed); /* #767676 / #1D1D1D            */
  --text:            var(--text-default);
  --muted:           var(--text-secondary);
  --text-dis:        var(--text-disabled);
  --reverse:         var(--text-reverse);                /* #FFF in both modes           */
  --on-inverse:      var(--text-on-inverse);             /* flips: label on ink button   */
  --icon:            var(--icon-default);
  --icon-rev:        var(--icon-default-reverse);
  /* lines */
  --border:          var(--border-subtle);               /* #D7D8D6 / #404040            */
  --line-strong:     var(--border-strong);
  --divider:         var(--divider-border-section);      /* #D7D8D6 / #404040            */
  --divider-soft:    var(--divider-border-subsection);   /* #EDEDED / #212121            */
  --focus:           var(--focus-ring);                  /* #305A85 / #4587A7            */
  /* brand + button intents */
  --accent:          var(--primary-background-default);  /* #DB0011                      */
  --pri:             var(--primary-background-default);
  --pri-hover:       var(--primary-background-hover);
  --pri-pressed:     var(--primary-background-pressed);
  --pri-disabled:    var(--primary-background-disabled);
  --ink:             var(--secondary-background-default);/* inverting #000 / #FFF        */
  --ink-hover:       var(--secondary-background-hover);
  --ink-pressed:     var(--secondary-background-pressed);
  --ink-disabled:    var(--secondary-background-disabled);
  --ter:             var(--tertiary-background-default);
  --ter-hover:       var(--tertiary-background-hover);
