    clip:rect(0,0,0,0); white-space:nowrap; border:0;}
.cn-template-report .visually-hidden{position:absolute; width:1px; height:1px; margin:-1px; padding:0; border:0;
    clip:rect(0 0 0 0); clip-path:inset(50%); overflow:hidden; white-space:nowrap;}
.cn-template-report .l-stack, .cn-template-report .l-row, .cn-template-report .l-grid, .cn-template-report .l-split{--l-gap-xxs:2px; --l-gap-xs:4px; --l-gap-s:8px; --l-gap-m:12px;
    --l-gap-l:24px; --l-gap-xl:32px; --l-gap-xxl:48px;
    --l-gap:var(--l-gap-m);}
.cn-template-report .l-stack[data-gap="s"], .cn-template-report .l-row[data-gap="s"], .cn-template-report .l-grid[data-gap="s"], .cn-template-report .l-split[data-gap="s"]{--l-gap:var(--l-gap-s);}
.cn-template-report .l-stack[data-gap="l"], .cn-template-report .l-row[data-gap="l"], .cn-template-report .l-grid[data-gap="l"], .cn-template-report .l-split[data-gap="l"]{--l-gap:var(--l-gap-l);}
.cn-template-report .l-stack[data-gap="xl"], .cn-template-report .l-row[data-gap="xl"], .cn-template-report .l-grid[data-gap="xl"], .cn-template-report .l-split[data-gap="xl"]{--l-gap:var(--l-gap-xl);}
.cn-template-report .l-stack[data-gap="xxl"], .cn-template-report .l-row[data-gap="xxl"], .cn-template-report .l-grid[data-gap="xxl"], .cn-template-report .l-split[data-gap="xxl"]{--l-gap:var(--l-gap-xxl);}
.cn-template-report .l-container{--l-max:1120px; width:100%; max-width:var(--l-max); margin-inline:auto;
    padding-inline:var(--l-margin);}
.cn-template-report .l-stack{display:flex; flex-direction:column; gap:var(--l-gap);}
.cn-template-report .l-stack > *{margin-block:0;}
.cn-template-report .l-row{display:flex; flex-direction:row; flex-wrap:wrap; gap:var(--l-gap); align-items:center;}
.cn-template-report .l-row[data-align="baseline"]{align-items:baseline;}
.cn-template-report .l-row[data-justify="between"]{justify-content:space-between;}
.cn-template-report .l-row[data-justify="end"]{justify-content:flex-end;}
.cn-template-report .l-grid{display:grid; --l-min:240px;
    grid-template-columns:repeat(auto-fill, minmax(min(var(--l-min), 100%), 1fr));
    gap:var(--l-gap);}
.cn-template-report .l-split{display:grid; gap:var(--l-gap); grid-template-columns:minmax(0, 1fr) 280px;
    container-type:inline-size;}
.cn-template-report .l-measure{max-width:64ch;}
@container (max-width: 760px){
/* breakpoint/ms, measured against the CONTAINER */
.cn-template-report .l-split{grid-template-columns:minmax(0, 1fr);}
}
.cn-template-report nav.tpl-crumbs ol{list-style:none; display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin:0; padding:0;}
.cn-template-report nav.tpl-crumbs li{display:inline-flex; align-items:center; gap:8px;}
.cn-template-report .sep{color:var(--text); opacity:var(--alpha-52); display:inline-flex; align-items:center;}
.cn-template-report .sep .chev{width:11px; height:11px; display:block; fill:currentColor;}
.cn-template-report a.crumb{color:var(--text); text-decoration:underline; text-underline-offset:3px; text-decoration-thickness:1px;}
.cn-template-report a.crumb:hover{text-decoration-thickness:2px;}
.cn-template-report a.crumb:focus-visible{outline:none; text-decoration:none; box-shadow:inset 0 -2px 0 var(--text);}
/* ⚠ Breadcrumbs' own rule here is `{font-weight:500; opacity:var(--alpha-84)}`. The WEIGHT half
     is a raw font declaration and the TYPE gate catches it — correctly. It is NOT re-declared:
     the current crumb carries `.t-cm-ctl-14` (14px/500) in the markup instead of the siblings'
     `.t-cm-caption` (14px/400), which is the same 14/500 through the canon ramp. Same pixels,
     zero TYPE-002 contribution. The opacity half is copied unchanged. */
.cn-template-report nav.tpl-crumbs [aria-current="page"]{opacity:var(--alpha-84);}
/* Headers `.display`: the h1 + subtitle pair. GEOMETRY copied; its `font:400 32px/1.1` and
     `font:400 16px/1.5` are NOT copied — `.t-ed-heading-2` (28/36) and `.t-ed-body` (16/24) carry
     the type from the canon ramp instead. 32px is on the ramp too (`.t-cm-heading`) but it is a
     SINGLE-LINE component composite and a page title wraps, so the deciding rule (wrapping ⇒
     Editorial) sends it to heading-2. ⬛ THE SIZE STEP DOWN, 32 → 28, IS VISIBLE AND IS DAVE'S. */
.cn-template-report .tpl-display h1{margin:0; letter-spacing:-.01em;}
.cn-template-report .tpl-display p{margin:8px 0 0; opacity:var(--alpha-80);}
.cn-template-report .btn{height:44px; min-width:96px; padding:0 20px; border:0; border-radius:var(--border-radius-control);
    cursor:pointer; justify-content:center; gap:8px;
    transition:background var(--ease), border-color var(--ease), transform var(--spring), filter var(--press);}
.cn-template-report .btn:focus-visible{outline:2px solid var(--ter-label); outline-offset:2px;}
/* ===== PARTIAL press-physics (button-family — Button.reference.html is the source of truth) ===== */
.cn-template-report .btn:hover{transform:scale(calc(1 + var(--press-travel)/var(--phys-size)));}
.cn-template-report .btn.full:hover{transform:none;}
.cn-template-report .btn:active{transform:scale(calc(1 - var(--press-travel)/var(--phys-size))); filter:brightness(var(--press-darken)); transition:transform var(--press), filter var(--press);}
@media (prefers-reduced-motion: reduce){
.cn-template-report .btn:hover, .cn-template-report .btn:active{transform:none !important; filter:none !important;}
}
/* ===== PARTIAL press-physics END ===== */
.cn-template-report .btn.primary{background:var(--pri-default); color:var(--pri-label);}
.cn-template-report .btn.primary:hover{background:color-mix(in srgb, var(--pri-default) 68%, var(--page));}
.cn-template-report .btn.tertiary{background:transparent; color:var(--ter-label); border:1px solid var(--ter-border);}
.cn-template-report .btn.tertiary:hover{background:var(--ter-hover);}
.cn-template-report .btn.quaternary{background:transparent; color:var(--quat-label);}
.cn-template-report .btn.quaternary:hover{background:var(--quat-hover);}
.cn-template-report .btn svg{width:16px; height:16px; fill:currentColor; flex:none;}
/* ---- the period switcher — View-options `.seg`, via Template-dashboard ---- */
.cn-template-report .seg{position:relative; display:inline-flex; border:1px solid var(--fborder); background:var(--surface);}
.cn-template-report .seg .ind{position:absolute; top:0; bottom:0; left:0; width:0; background:var(--sel); z-index:0;
