.cn-template-report .seg button{position:relative; z-index:1; display:inline-flex; align-items:center; gap:8px; height:40px; padding:0 16px;
    border:0; background:transparent; color:var(--text); cursor:pointer; transition:color var(--move);}
.cn-template-report .seg button:not([aria-pressed="true"]):hover{background:var(--hover);}
.cn-template-report .seg button[aria-pressed="true"]{color:var(--on-sel);}
.cn-template-report .seg button:focus-visible{outline:2px solid var(--focus); outline-offset:-2px; z-index:2;}
.cn-template-report .seg svg{width:16px; height:16px; fill:currentColor;}
