.cn-template-report .spark-inline[data-trend="up"] .dv-series{stroke:var(--spark-up);}
.cn-template-report .spark-inline[data-trend="up"] .dv-end{fill:var(--spark-up);}
.cn-template-report .spark-inline[data-trend="down"] .dv-series{stroke:var(--spark-down);}
.cn-template-report .spark-inline[data-trend="down"] .dv-end{fill:var(--spark-down);}
