.cn-template-report .kpi-cta:hover{opacity:var(--alpha-96);}
.cn-template-report .kpi-cta:focus-visible{outline:2px solid var(--focus); outline-offset:-2px; opacity:var(--alpha-96);}
.cn-template-report .kpi-tile.has-cta .lbl16{padding-right:40px;}
