.cn-template-report .summary__row:last-child{border-bottom:0;}
.cn-template-report .summary__k{color:var(--text); opacity:var(--alpha-60); margin:0;}
.cn-template-report .summary__v{color:var(--text); font-variant-numeric:tabular-nums; text-align:right; margin:0;}
/* ---- RAG status chip — Status-indicator form B, via Document-row ---- */
