.cn-template-report .status .dot{width:8px; height:8px; border-radius:50%; flex:none;}
.cn-template-report .status.ok{background:var(--success-tint);}
.cn-template-report .status.ok .dot{background:var(--success);}
.cn-template-report .status.warn{background:var(--warning-tint);}
.cn-template-report .status.warn .dot{background:var(--warning);}
.cn-template-report .status.err{background:var(--error-tint);}
.cn-template-report .status.err .dot{background:var(--error);}
.cn-template-report .status.inf{background:var(--info-tint);}
.cn-template-report .status.inf .dot{background:var(--info);}
/* ---- charts — Chart-bar.reference.html (the shared dv spine) ---- */
.cn-template-report figure.dv{margin:0; position:relative;}
.cn-template-report .dv-head{display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:8px 16px; margin:0 0 12px;}
.cn-template-report .dv-title{margin:0;}
.cn-template-report .dv-stage{overflow-x:auto; padding-bottom:4px;}
.cn-template-report .dv-chart-area{width:580px;}
.cn-template-report .dv-svg{display:block; width:580px; height:260px; overflow:visible;}
.cn-template-report .dv-grid{stroke:var(--data-grid); stroke-opacity:var(--grid-alpha); stroke-width:1;}
.cn-template-report line.dv-axis{stroke:var(--baseline); stroke-width:1;}
.cn-template-report text.dv-axis, .cn-template-report text.dv-label{opacity:var(--axis-alpha);}
.cn-template-report rect.dv-series{transition:filter var(--ease), opacity var(--ease), visibility var(--ease);}
.cn-template-report rect.dv-series:hover{filter:brightness(1.12);}
[data-theme="dark"] .cn-template-report rect.dv-series:hover{filter:brightness(1.22);}
.cn-template-report .dv-series[tabindex]:focus-visible{outline:2px solid var(--ink); outline-offset:2px;}
/* ---- Chart-line — Chart-line.reference.html, declaration-for-declaration, for the parts the
