.cn-template-report .dv-marker:focus-visible{outline:2px solid var(--ink);}
.cn-template-report polyline.dv-series, .cn-template-report g.dv-marker, .cn-template-report text.dv-endkey{transition:opacity var(--ease), visibility var(--ease);}
