.cn-template-report .dgsearch input[type="search"]::-webkit-search-cancel-button{-webkit-appearance:none; appearance:none;}
.cn-template-report .dgsearch:hover{background:var(--hover);}
.cn-template-report .dgsearch:focus-within{border-color:var(--bar); box-shadow:inset 0 -4px 0 0 var(--bar); background:var(--page);}
