.cn-template-report .fchip .x{position:relative; display:inline-flex; width:24px; height:24px; padding:0; border:0; background:transparent;
    color:var(--icon); cursor:pointer; align-items:center; justify-content:center; flex:0 0 auto;
    transition:color var(--ease), transform var(--spring);}
.cn-template-report .fchip .x svg{width:12px; height:12px; fill:currentColor;}
.cn-template-report .fchip .x:focus-visible{outline:2px solid var(--focus); outline-offset:2px;}
.cn-template-report .dg-scroll{overflow-x:auto; border:1px solid var(--border); border-radius:var(--border-radius-surface);}
.cn-template-report .dg table{border-collapse:collapse; width:100%; min-width:640px; background:var(--cell);}
.cn-template-report .dg th, .cn-template-report .dg td{padding:var(--cell-py) var(--cell-px); border:1px solid var(--border); text-align:left; vertical-align:middle;
    color:var(--text);}
.cn-template-report .dg thead th{background:var(--header); position:sticky; top:0; z-index:2; padding:0;}
.cn-template-report .dg td.num{text-align:right;}
