    transition:background var(--ease), transform var(--spring), filter var(--press);}
.cn-template-report .sort:hover{background:var(--hover);}
.cn-template-report .sort:focus-visible{outline:2px solid var(--focus); outline-offset:-2px;}
.cn-template-report .sort .ic{display:none; flex:none; width:16px; height:16px; margin-left:auto;}
