.cn-template-report .dg th[aria-sort="descending"] .ic-desc{display:inline-flex;}
.cn-template-report .dg tbody tr{transition:background var(--ease);}
.cn-template-report .dg tbody tr:hover td{background:var(--hover);}
.cn-template-report .dg-foot{display:flex; gap:12px 16px; align-items:center; flex-wrap:wrap; margin-top:12px;}
.cn-template-report .dg-range{opacity:var(--alpha-60);}
.cn-template-report .dg-pp{display:flex; gap:8px; align-items:center; margin-left:auto;}
.cn-template-report nav.dgpg ul{list-style:none; display:flex; gap:4px; align-items:center; margin:0; padding:0;}
.cn-template-report .pbtn{min-width:44px; height:44px; display:inline-flex; align-items:center; justify-content:center; padding:0 8px;
