    --phys-size:44;
    transition:background var(--ease), color var(--ease), transform var(--spring), filter var(--press);}
.cn-template-report .pbtn:not([disabled]):hover{background:var(--hover);}
.cn-template-report .pbtn:not([disabled]):active{background:var(--pressedbg); color:var(--onpressed);}
.cn-template-report .pbtn:focus-visible{outline:2px solid var(--focus); outline-offset:-2px;}
.cn-template-report .pbtn[aria-current="page"]{border-color:var(--currentbd);}
